import{_ as l,l as r,o as a,c as s,v as i,p as c,x as o,d as n,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"分解着色冲突","description":"","frontmatter":{"title":"分解着色冲突","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/decomposition-coloring-conflict.md","filePath":"litho/decomposition-coloring-conflict.md","lastUpdated":1789023840000}'),d={name:"litho/decomposition-coloring-conflict.md"};function p(m,t,_,A,f,u){const e=r("Mermaid");return a(),s("div",null,[t[1]||(t[1]=i('<h1 id="分解着色冲突" tabindex="-1">分解着色冲突 <a class="header-anchor" href="#分解着色冲突" aria-label="Permalink to &quot;分解着色冲突&quot;">​</a></h1><div class="epigraph"><p>双重图形先是一张冲突图能不能染色；奇圈、stitch 和三色不足，不是 OPC 修边能消掉的红。</p><footer>—— 对照双重/多重图形着色、冲突图与 stitch 的公开算法传统；[LELE 颜色分解](/litho/lele-color-decomposition) 已钉过两次曝光</footer></div><p><a href="/litho/ml-hotspot-prediction">上一课</a>把学习模型限制在排序。缺口是分解：间距小于单次可印极限的边必须分到不同曝光（不同「色」），这是图论约束，不是风险分。<a href="/litho/lele-color-decomposition">LELE 颜色分解</a> 已写两次曝光的染色；本课把冲突收进签核门：LRC 必须能报无法着色，而不是留给掩模厂。设计规则为何长成现在这样，留给[下一课](/litho/design-rule-origin）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单次 EUV 或浸没仍覆盖不了的节距，用 LELE、LELELE、切线或多色金属。冲突图：多边形（或边段）为顶点，间距小于最小同色间距则连边。2-色可染当且仅当图是二分的；奇圈即冲突。三重曝光对应 3-色，成本跳一层掩模与套刻。SADP/SAQP 不是染色，芯轴与 spacer 的「颜色」是自对准的，冲突形态不同，本课不改写成 spacer 工艺。</p><p>缺口是<strong>签核时的冲突</strong>，不是重讲一遍 LELE 流程。布线器在合法 DRC 下仍可画出奇圈；LFD 若没把可染性当约束，热点预测再准也修不回一张不可分解的网。</p><h3 id="stitch-是冲突的另一种债" tabindex="-1">stitch 是冲突的另一种债 <a class="header-anchor" href="#stitch-是冲突的另一种债" aria-label="Permalink to &quot;stitch 是冲突的另一种债&quot;">​</a></h3><p>同一根导线被拆到两色，接头（stitch）引入套刻敏感的接缝和局部 CD。允许 stitch 可以消灭部分奇圈，却把套刻预算写进导线可靠性。禁止 stitch 则更多设计必须改拓扑。合同要声明：本层是否允许 stitch、最小重叠、是否禁止在 via 落点。</p><p><span class="marginnote">着色冲突是硬失败：没有「OPC 再跑一晚」这回事。报告应指向圈上的边，而不是一串 EPE 纳米。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分解工具：冲突图构建（含投影间距、jog、via 覆盖）、染色启发式、stitch 候选、合法化。签核：LRC 甲板含「未着色 / 同色间距 / stitch 规则」。与设计协同：轨道方向、via 网格、优选节距使图更易二分——这是 LFD 的分解侧。与 <a href="/litho/cut-mask-dpt">切线多重</a> 的关系：切线层有自己的冲突，不要和金属色混报。</p><p>换节点若从 LELE 改 EUV 单次，冲突图应整层删除，而不是留着旧色当装饰规则。</p><p>冲突报告要能回到版图坐标和圈上的边，供布线器或手工改拓扑。只报「本层冲突数」无法修。DPT 着色文献把 stitch 规则写成与最小同色间距并列的条款，LRC 甲板应同样并列，而不是藏在 OPC 日志里。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最小同色间距来自光学 + 套刻：两次曝光的相对位移把「不同色」的有效间距吃掉一截，所以着色规则比单次最小间隔更宽。奇圈无法 2-染是组合事实。工具用删除边（改设计）、加 stitch（改几何）、或加色（加掩模）三条路；三条都有成本函数，DTCO 已在上游选过哪条路允许。</p>',15)),(a(),c(E,null,{default:o(()=>[h(e,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAY%5B%22%E9%87%91%E5%B1%9E%20%2F%20%E5%88%87%E7%BA%BF%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20CG%5B%22%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%0A%20%20CG%20--%3E%20COL%5B%22k-%E6%9F%93%E8%89%B2%22%5D%0A%20%20COL%20--%3E%20OK%5B%22%E5%8F%AF%E5%88%86%E8%A7%A3%22%5D%0A%20%20COL%20--%3E%20ODD%5B%22%E5%A5%87%E5%9C%88%20%2F%20%E8%89%B2%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20ODD%20--%3E%20ST%5B%22stitch%20%E6%88%96%E6%94%B9%E8%AE%BE%E8%AE%A1%E6%88%96%E5%8A%A0%E8%89%B2%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>着色不保证可印：同色合法仍可能是光学热点。不把某分解器的「冲突为零」当硅上良率。本课不写限价簿，也不把图染色算法竞赛当光刻物理。</p><p>后课默认：不可着色是挡磁带的硬规则。下一课从这些硬规则回溯：设计手册里的数字从哪来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>着色冲突是冲突图可染性，OPC 修不掉奇圈。</li><li>stitch 用套刻债换可染性，必须进层合同。</li><li>LRC 要报圈与同色间距，而不是只报 EPE。</li><li>出处：DPT 着色与冲突图传统；LELE 分解公开论述。</li></ul>',5))])}const C=l(d,[["render",p]]);export{L as __pageData,C as default};
